package dev.veltraph.client.combat.quiver;
import dev.veltraph.client.gui.MenuSnapshot;
import java.math.BigDecimal;
import java.util.*;
import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;
class QuiverRefillRuntimeTest {
    private static final QuiverRefillRuntime.Item ARROW=new QuiverRefillRuntime.Item("minecraft:arrow","Arrow","plain",0);
    private static QuiverRefillRuntime.Settings settings(QuiverSupply mode){return new QuiverRefillRuntime.Settings("Quiver Shop","Fill your Quiver",ARROW,64,20,"Refill: {quantity}x {item} for {cost} Coins","You filled your quiver with {quantity} {item} for {cost} coins!",3,20,mode,"Quiver","Stored: {quantity}x {item}",true);}
    private static MenuSnapshot menu(int id,int revision,int price,int stored){return new MenuSnapshot(id,"Quiver Shop",List.of(new MenuSnapshot.Slot(11,"Fill your Quiver",List.of("Refill: 64x Arrow for "+price+" Coins"),false),new MenuSnapshot.Slot(20,"Quiver",List.of("Stored: "+stored+"x Arrow"),false)),revision);}
    private static QuiverRefillRuntime started(QuiverSupply mode){var r=new QuiverRefillRuntime();r.start(menu(1,0,16,0),List.of(),new BigDecimal(1000),settings(mode),0,true);return r;}
    private static void purchase(QuiverRefillRuntime r){var a=r.tick(menu(1,0,16,0),List.of(),new BigDecimal(1000),3,true,false).orElseThrow();assertTrue(r.validates(a,menu(1,0,16,0)));r.applied(a,true);}
    @Test void actualOwnedQuiverAndFundsAndMessageRequired(){var r=started(QuiverSupply.CONTAINER);purchase(r);r.onMessage("You filled your quiver with 64 Arrow for 16 coins!");r.tick(menu(1,1,16,64),List.of(),new BigDecimal(984),4,true,false);assertEquals(QuiverRefillRuntime.State.CLOSING,r.state());var close=r.tick(menu(1,1,16,64),List.of(),new BigDecimal(984),5,true,false).orElseThrow();r.applied(close,true);r.tick(null,List.of(),new BigDecimal(984),6,true,false);assertEquals(QuiverRefillRuntime.State.COMPLETE,r.state());}
    @Test void playerArrowsCannotStandInForHiddenQuiver(){var r=started(QuiverSupply.CONTAINER);purchase(r);r.onMessage("You filled your quiver with 64 Arrow for 16 coins!");r.tick(menu(1,1,16,0),List.of(new QuiverRefillRuntime.Item(ARROW.id(),ARROW.name(),ARROW.components(),64)),new BigDecimal(984),4,true,false);assertEquals(QuiverRefillRuntime.State.WAIT_ACK,r.state());}
    @Test void noOptimisticAckOnCountOrReceiptAlone(){for(int half=0;half<3;half++){var r=started(QuiverSupply.CONTAINER);purchase(r);if(half!=0)r.onMessage("You filled your quiver with 64 Arrow for 16 coins!");r.tick(menu(1,1,16,half==1?0:64),List.of(),new BigDecimal(half==2?1000:984),4,true,false);assertEquals(QuiverRefillRuntime.State.WAIT_ACK,r.state());r.tick(menu(1,1,16,64),List.of(),new BigDecimal(984),21,true,false);assertEquals(QuiverRefillRuntime.State.FAILED,r.state());}}
    @Test void vanillaInventoryModeIsSeparatelyAcknowledged(){var r=started(QuiverSupply.PLAYER_INVENTORY);purchase(r);r.onMessage("You filled your quiver with 64 Arrow for 16 coins!");r.tick(menu(1,1,16,0),List.of(new QuiverRefillRuntime.Item(ARROW.id(),ARROW.name(),ARROW.components(),64)),new BigDecimal(984),4,true,false);assertEquals(QuiverRefillRuntime.State.CLOSING,r.state());}
    @Test void changedPriceNeverIssuesPurchase(){var r=started(QuiverSupply.CONTAINER);assertTrue(r.tick(menu(1,1,17,0),List.of(),new BigDecimal(1000),3,true,false).isEmpty());assertEquals(QuiverRefillRuntime.State.FAILED,r.state());}
    @Test void replacementAndCursorOwnershipCancel(){var r=started(QuiverSupply.CONTAINER);assertTrue(r.tick(menu(2,1,16,0),List.of(),new BigDecimal(1000),3,true,false).isEmpty());assertEquals(QuiverRefillRuntime.State.CANCELLED,r.state());r=started(QuiverSupply.CONTAINER);r.tick(menu(1,0,16,0),List.of(),new BigDecimal(1000),3,false,false);assertEquals(QuiverRefillRuntime.State.CANCELLED,r.state());}
    @Test void staleRevisionRejectedAtActionBoundary(){var r=started(QuiverSupply.CONTAINER);var a=r.tick(menu(1,0,16,0),List.of(),new BigDecimal(1000),3,true,false).orElseThrow();assertFalse(r.validates(a,menu(1,1,16,0)));r.applied(a,false);assertEquals(QuiverRefillRuntime.State.FAILED,r.state());}
    @Test void unknownContractAndOverBudgetFailClosed(){assertThrows(IllegalArgumentException.class,()->new QuiverRefillRuntime.Settings("","",ARROW,64,20,"","",3,20,QuiverSupply.CONTAINER,"","",true));var r=new QuiverRefillRuntime();r.start(menu(1,0,21,0),List.of(),new BigDecimal(1000),settings(QuiverSupply.CONTAINER),0,true);assertEquals(QuiverRefillRuntime.State.FAILED,r.state());}
    @Test void wrongItemQuantityOrCostReceiptsCannotResume(){for(var receipt:List.of("You filled your quiver with 32 Arrow for 16 coins!","You filled your quiver with 64 Spectral Arrow for 16 coins!","You filled your quiver with 64 Arrow for 17 coins!")){var r=started(QuiverSupply.CONTAINER);purchase(r);r.onMessage(receipt);r.tick(menu(1,1,16,64),List.of(),new BigDecimal(984),4,true,false);assertEquals(QuiverRefillRuntime.State.WAIT_ACK,r.state());}}
    @Test void exactPurseDebitCanAcknowledgeCostAbsentFromFilledMessage(){var options=new QuiverRefillRuntime.Settings("Quiver Shop","Fill your Quiver",ARROW,64,20,"Refill: {quantity}x {item} for {cost} Coins","You filled your quiver with {quantity} {item}!",3,20,QuiverSupply.CONTAINER,"Quiver","Stored: {quantity}x {item}",true);var r=new QuiverRefillRuntime();r.start(menu(1,0,16,0),List.of(),new BigDecimal(1000),options,0,true);purchase(r);r.onMessage("You filled your quiver with 64 Arrow!");r.tick(menu(1,1,16,64),List.of(),new BigDecimal(984),4,true,false);assertEquals(QuiverRefillRuntime.State.CLOSING,r.state());}
    @Test void receiptCostRequiredWhenCurrencyUnavailable(){var base=settings(QuiverSupply.CONTAINER);var options=new QuiverRefillRuntime.Settings(base.title(),base.button(),ARROW,64,20,base.quoteTemplate(),base.ackTemplate(),3,20,QuiverSupply.CONTAINER,"Quiver","Stored: {quantity}x {item}",false);var r=new QuiverRefillRuntime();r.start(menu(1,0,16,0),List.of(),null,options,0,true);var action=r.tick(menu(1,0,16,0),List.of(),null,3,true,false).orElseThrow();r.applied(action,true);r.onMessage("You filled your quiver with 64 Arrow for 16 coins!");r.tick(menu(1,1,16,64),List.of(),null,4,true,false);assertEquals(QuiverRefillRuntime.State.CLOSING,r.state());}
    @Test void samePriceDoesNotPermitChangedNativeButtonItem(){var r=started(QuiverSupply.CONTAINER);var original=menu(1,0,16,0);var slots=new ArrayList<>(original.slots());var old=slots.getFirst();slots.set(0,new MenuSnapshot.Slot(old.id(),old.name(),old.lore(),false,"minecraft:diamond"));assertTrue(r.tick(new MenuSnapshot(1,original.title(),slots,1),List.of(),new BigDecimal(1000),3,true,false).isEmpty());assertEquals(QuiverRefillRuntime.State.FAILED,r.state());}
    @Test void serverCloseCanFollowOwnedCountUpdateBeforeNextTick(){var r=started(QuiverSupply.CONTAINER);purchase(r);r.observeClosedSupply(menu(1,1,16,64));r.onMessage("You filled your quiver with 64 Arrow for 16 coins!");r.tick(null,List.of(),new BigDecimal(984),4,true,false);assertEquals(QuiverRefillRuntime.State.COMPLETE,r.state());r=started(QuiverSupply.CONTAINER);purchase(r);r.observeClosedSupply(menu(2,1,16,64));r.onMessage("You filled your quiver with 64 Arrow for 16 coins!");r.tick(null,List.of(),new BigDecimal(984),4,true,false);assertEquals(QuiverRefillRuntime.State.WAIT_ACK,r.state());}
}
